require __DIR__.'/../includes/exam_mapping_service.php';
$admin=(int)$f['ids']['school_admin'];$super=(int)$db->query("SELECT id FROM users WHERE role='super_admin'")->fetchColumn();
$templates=examTemplates($db);erpEqual(count($templates),3,'First, second and final templates are available');
$template=$templates[0];$input=['name'=>'First Term Standard','type'=>'terminal','has_internal'=>'1','result_system'=>'gpa','date_calendar'=>'BS','date_format'=>'ymd','term_no'=>'1','is_active'=>'1','revision'=>$template['revision']];
$saved=saveExamTemplate($db,$super,(int)$template['id'],$input);erpEqual($saved['revision'],2,'Template revisions advance');
$catalog=examTemplateCatalog($db);$local=$db->query('SELECT cs.*,c.name class_name,s.name_en,s.code,s.source_id FROM class_subjects cs JOIN classes c ON c.id=cs.class_id JOIN subjects s ON s.id=cs.subject_id WHERE cs.class_id='.(int)$f['class'].' AND cs.subject_id='.(int)$f['subject'])->fetch();
$source=examTemplateSchemeForClass($catalog,$local);$sourceId=(int)$source['id'];
$conflict=[...$source,'id'=>99999,'source_subject_id'=>99999,'curriculum_key'=>'OTHER-KEY','name_en'=>'Changed local label','code'=>$source['code']];
$renamed=[...$local,'curriculum_key'=>$source['curriculum_key'],'source_id'=>$source['source_subject_id'],'name_en'=>'Changed local label'];
erpEqual(examTemplateSchemeForClass([$source,$conflict],$renamed)['id'],$source['id'],'Stable curriculum identity takes precedence over coincidental names or reused codes');
