$saved=saveExamTemplate($db,$super,(int)$template['id'],[...$input,'revision'=>2,'schemes'=>[$sourceId=>$custom]]);erpEqual($saved['revision'],3,'Class subject overrides have their own saved revision');
erpReject(fn()=>saveExamTemplate($db,$super,(int)$template['id'],[...$input,'revision'=>3,'schemes'=>[$sourceId=>[...$custom,'theory_pass'=>71]]]),'Invalid template pass limits rejected');
erpReject(fn()=>saveExamTemplate($db,$admin,(int)$template['id'],$input),'School admin cannot change system defaults');
erpReject(fn()=>saveExamTemplate($db,$super,(int)$template['id'],$input),'Stale template update rejected');
erpReject(fn()=>createExamFromTemplate($db,1,$admin,['creation_mode'=>'automatic','template_id'=>$template['id'],'template_revision'=>1]),'Stale creation form must reload changed defaults');
$db->exec("INSERT INTO academic_years(school_id,year_bs,year_ad,is_active,is_hidden) VALUES(1,'2080','2023',0,0)");$chosenYear=(int)$db->lastInsertId();
$create=['creation_mode'=>'automatic','template_id'=>$template['id'],'academic_year_id'=>$chosenYear,'name'=>'Forged school name','type'=>'unit','has_internal'=>'0','result_system'=>'percentage','start_date'=>'2026-10-10','end_date'=>'2026-10-15'];
$automatic=createExamFromTemplate($db,1,$admin,$create);
$exam=schoolRecord($db,'exams',$automatic,1);erpEqual([$exam['name'],$exam['type'],(int)$exam['has_internal'],$exam['result_system']],['First Term Standard','terminal',1,'gpa'],'Automatic mode ignores forged setting overrides');
erpCheck((bool)$exam['template_snapshot'],'Creation retains a template snapshot');
erpEqual((int)$exam['academic_year_id'],$chosenYear,'Schools choose a visible academic year independently of locked defaults');
$db->prepare("INSERT INTO academic_years(school_id,year_bs,year_ad,is_active,is_hidden) VALUES(?,'2080','2023',0,0)")->execute([$f['otherSchool']]);$foreignYear=(int)$db->lastInsertId();
erpReject(fn()=>createExamFromTemplate($db,1,$admin,[...$create,'academic_year_id'=>$foreignYear]),'Foreign school academic years are rejected');
erpReject(fn()=>createExamFromTemplate($db,1,$admin,[...$create,'academic_year_id'=>[$chosenYear]]),'Malformed academic year fields are rejected');
$db->exec("INSERT INTO academic_years(school_id,year_bs,year_ad,is_active,is_hidden) VALUES(1,'2079','2022',0,1)");$hiddenYear=(int)$db->lastInsertId();
erpReject(fn()=>createExamFromTemplate($db,1,$admin,[...$create,'academic_year_id'=>$hiddenYear]),'Hidden academic years are unavailable for new exams');
$q=$db->prepare('SELECT * FROM exam_subjects WHERE exam_id=? AND class_id=? AND subject_id=?');$q->execute([$automatic,$f['class'],$f['subject']]);$mapping=$q->fetch();erpCheck((bool)$mapping,'Automatic mode initializes class subjects');
erpEqual([(float)$mapping['theory_full'],(float)$mapping['practical_full']],[70.0,30.0],'Automatic mode loads the customized super-admin class subject scheme');
erpEqual([$exam['start_date'],$exam['end_date'],$exam['date_calendar'],$exam['date_format']],['2026-10-10','2026-10-15','BS','ymd'],'School dates are retained with default print settings');
erpReject(fn()=>updateExamDetails($db,1,$automatic,['name'=>'Changed']),'Automatic exam details cannot be edited');
erpReject(fn()=>saveExamMapping($db,1,$automatic,$mapping,(int)$mapping['id'],$admin),'Automatic mapping cannot be edited');
$old=$exam['template_snapshot'];saveExamTemplate($db,$super,(int)$template['id'],[...$input,'revision'=>3,'name'=>'Updated Future Default','schemes'=>[$sourceId=>[...$custom,'theory_full'=>60,'practical_full'=>40]]]);
erpEqual(schoolRecord($db,'exams',$automatic,1)['template_snapshot'],$old,'Later template edits do not rewrite existing exam snapshots');
$q->execute([$automatic,$f['class'],$f['subject']]);erpEqual($q->fetch(),$mapping,'Later defaults do not rewrite prior subject limits');
$manual=createExamFromTemplate($db,1,$admin,['creation_mode'=>'manual','template_id'=>$template['id'],'name'=>'School Custom Exam','type'=>'terminal','has_internal'=>'1','result_system'=>'percentage']);
$row=schoolRecord($db,'exams',$manual,1);erpEqual([$row['name'],$row['result_system'],$row['creation_mode']],['School Custom Exam','percentage','manual'],'Manual mode permits school settings');
updateExamDetails($db,1,$manual,['name'=>'Edited school exam','type'=>'terminal','has_internal'=>'1','result_system'=>'gpa']);erpEqual(schoolRecord($db,'exams',$manual,1)['name'],'Edited school exam','Manual exam stays editable');
changeExamState($db,1,$automatic,'lock');changeExamState($db,1,$automatic,'reopen');erpEqual((int)schoolRecord($db,'exams',$automatic,1)['is_locked'],0,'Automatic exam still allows lock/reopen');
$before=$db->query('SELECT COUNT(*) FROM exams')->fetchColumn();erpReject(fn()=>createExamFromTemplate($db,2,$admin,$create),'Cross-school creation blocked');erpEqual($db->query('SELECT COUNT(*) FROM exams')->fetchColumn(),$before,'Rejected creation is atomic');
// A custom-only subject may use school defaults in manual mode, never in automatic mode.
