$db->prepare('INSERT INTO class_subjects(school_id,class_id,subject_id,credit_hours,th_full_marks,th_pass_marks,in_full_marks,in_pass_marks,is_active) VALUES(1,?,?,4,100,35,0,0,1)')->execute([$f['class'],$extra]);
$count=$db->query('SELECT COUNT(*) FROM exams')->fetchColumn();erpReject(fn()=>createExamFromTemplate($db,1,$admin,$create),'Automatic mode cannot silently adopt school-only scheme settings');erpEqual($db->query('SELECT COUNT(*) FROM exams')->fetchColumn(),$count,'Unsupported automatic default rolls back the whole creation');
$customExam=createExamFromTemplate($db,1,$admin,['creation_mode'=>'manual','template_id'=>$template['id'],'name'=>'Custom-only curriculum']);
$q->execute([$customExam,$f['class'],$extra]);erpCheck((bool)$q->fetch(),'Manual mode retains school-specific subjects');
// A genuine old shape upgrades without reclassifying or resetting existing exams.
$existing=$db->query('SELECT id,name,type,has_internal,result_system FROM exams ORDER BY id')->fetchAll();
$q->closeCursor();
foreach(['exam_templates','exam_template_history'] as $table)$db->exec('DROP TABLE '.$table);
foreach(['creation_mode','template_id','template_revision','template_snapshot'] as $column)$db->exec('ALTER TABLE exams DROP COLUMN '.$column);
$db->exec("UPDATE app_meta SET meta_value='11' WHERE meta_key='workflow_schema'");migrateSchoolExtensions($db);
erpEqual($db->query('SELECT id,name,type,has_internal,result_system FROM exams ORDER BY id')->fetchAll(),$existing,'Schema11 to12 preserves every exam setting and ID');
erpEqual($db->query('SELECT DISTINCT creation_mode FROM exams')->fetchAll(PDO::FETCH_COLUMN),['manual'],'Legacy exams remain manually editable, not retroactively locked');
migrateSchoolExtensions($db);erpEqual(count(examTemplates($db)),3,'Template migration is idempotent');
echo 'Exam templates passed: '.$GLOBALS['erp_checks']." checks\n";
